#!/bin/bash
set -e

# ==============================================================
# kaviancrypto v6.8 Pro Terminal - Complete All-in-One Installer
# 3 Live Visual & Structural Themes (Obsidian / Linear / TV Pro)
# + Live TP/SL Progress Bars + Sparklines + Split Strategy Studio
# + Dedicated Backup Bot Token + kaviancrypto v4.2 Default Strategy
# Fresh Install + Safe Repair/Upgrade (Preserves config.json,
# active_trades.json, sent_signals.json & custom_strategy.py)
# ==============================================================

APP_DIR="/opt/kaviancrypto"
PORT="8888"

echo "========================================================"
echo "  kaviancrypto v6.8 Pro - All-in-One Installer & Upgrade"
echo "  3 Adaptive UI Themes + Split Studio + v4.2 Strategy"
echo "========================================================"

echo "=== [1/6] Stopping existing service (if running) & preparing $APP_DIR ==="
systemctl stop kaviancrypto.service 2>/dev/null || true
mkdir -p "$APP_DIR"
cd "$APP_DIR"

# Save a copy of this installer so Backup & Security tab can download it anytime
SCRIPT_SRC="$(readlink -f "$0" 2>/dev/null || echo "$0")"
if [ -f "$SCRIPT_SRC" ] && [ "$SCRIPT_SRC" != "$APP_DIR/install_kaviancrypto_v6_8.sh" ]; then
    cp -f "$SCRIPT_SRC" "$APP_DIR/install_kaviancrypto_v6_8.sh" 2>/dev/null || true
    chmod +x "$APP_DIR/install_kaviancrypto_v6_8.sh" 2>/dev/null || true
fi

echo "=== [2/6] Installing system prerequisites ==="
apt-get update -y
apt-get install -y python3 python3-venv python3-pip curl

echo "=== [3/6] Extracting verified kaviancrypto v6.8 core files ==="
